using System;using System.IO;using System.Linq;using NUnit.Framework;using UnityEngine;using IdleIntelligence.Core;
namespace IdleIntelligence.Tests {
 [Serializable]public sealed class ResearchWorkV3Job{public string id;public double required,done,eventWork;}
 [Serializable]public sealed class ResearchWorkV3Step{public string action;public double at,boundary;public NumberData credits,data;public int quality;public long marker;public bool training;public int[] levels;public ResearchWorkV3Job[] jobs;}
 [Serializable]public sealed class ResearchWorkV3Flow{public string mode,cause;public bool active,prepared;public ResearchWorkV3Step[] steps;}
 [Serializable]public sealed class ResearchWorkV3Allocation{public double[] remaining,result;public double budget;}
 [Serializable]public sealed class ResearchWorkV3Cases{public string sourceHash;public bool productionEnabled;public ResearchWorkV3Flow[] flows;public ResearchWorkV3Allocation[] allocations;}
 public sealed class ItemSystemV3ResearchWorkTests {
  static ResearchWorkV3Cases Cases()=>JsonUtility.FromJson<ResearchWorkV3Cases>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/ItemV3ResearchWorkCases.json")));
  static GameState Prepared(string mode){var s=Game.New(1000,"prepared-research-work-reference");s.Legacy.prepared=true;if(mode!="normal")s.ItemSystemV3=new ItemV3State();s.Credits=s.Data=ScientificNumber.From(1e12);s.Quality=1;s.Research=Enumerable.Repeat(1,Balance.Research.Length).ToArray();s.Upgrades.purchasedLabs=3;s.Workshop.nodes=mode=="maximum"?new[]{"W10"}:Array.Empty<string>();string[] types=mode=="none"?Array.Empty<string>():mode=="photon"?new[]{"photonic-array"}:mode=="drone"?new[]{"lab-drone"}:mode=="pair"?new[]{"photonic-array","logic-seed"}:mode=="trio"?new[]{"photonic-array","logic-seed","lab-drone"}:new[]{"photonic-array","lab-drone"};foreach(string type in types){s=RetentionRules.CreateItem(s,type,mode=="maximum"?5:0);var item=s.Workshop.inventory.Last();if(mode=="maximum"){item.level=(int)ItemV3Balance.Get("levelMax");item.forge=(int)ItemV3Balance.Get("forgeMax");}s=Workshop.Equip(s,item.id,Workshop.EquipmentSlot(s,item.id));}if(mode=="unequipped")s.Workshop.equipped=new string[ItemBalance.Slots.Length];foreach(string id in new[]{"dataGeneration","materialAnalysis"}){var before=s;s=Game.Research(s,id);Assert.That(s,Is.Not.SameAs(before),"real paid research start "+id);}return s;}
  static void Near(ScientificNumber actual,NumberData row,string context){var expected=ScientificNumber.FromData(row);if(expected.IsZero)Assert.That(actual.IsZero,Is.True,context);else Assert.That(actual.Log10(),Is.EqualTo(expected.Log10()).Within(2e-10),context);}
  [Test]public void ActualPaidTrainingResearchWorkAndOfflineBoundariesMatchSource(){var c=Cases();Assert.That(c.sourceHash,Is.EqualTo(ItemV3Balance.SourceHash));Assert.That(c.productionEnabled,Is.False);Assert.That(c.flows.Length,Is.EqualTo(20));foreach(var flow in c.flows){var s=Prepared(flow.mode);foreach(var row in flow.steps){string label=flow.mode+" "+flow.active+" "+flow.cause+" "+row.action;switch(row.action){case"initial":break;case"training":s=Game.Train(s,"quality");Assert.That(s.Training,Is.Not.Null,label);break;case"ready":s=Game.Train(s,"quality");Assert.That(s.Training,Is.Not.Null,label);s.Training.done=s.Training.required;break;case"marker":case"duplicate":ItemSystemV3.CompleteTraining(s,flow.cause=="regular");break;case"finish":case"advance":case"reload-time":s=Game.Advance(s,row.at,flow.active);break;default:Assert.Fail(row.action);break;}Near(s.Credits,row.credits,label+" paid credits");Near(s.Data,row.data,label+" paid data");Assert.That(s.Quality,Is.EqualTo(row.quality),label);Assert.That(s.Training!=null,Is.EqualTo(row.training),label);Assert.That(s.ItemSystemV3?.lastCompletedTrainingSequence??0,Is.EqualTo(row.marker),label);Assert.That(s.Research,Is.EqualTo(row.levels),label);double boundary=ItemSystemV3.ResearchBoundary(s);Assert.That(double.IsPositiveInfinity(boundary)?-1:boundary,Is.EqualTo(row.boundary).Within(1e-7),label+" first true completion boundary");var jobs=PrestigeAutomation.ResearchJobs(s).ToArray();Assert.That(jobs.Length,Is.EqualTo(row.jobs.Length),label);foreach(var expected in row.jobs){var actual=jobs.Single(j=>j.id==expected.id);Assert.That(actual.required,Is.EqualTo(expected.required).Within(1e-8),label);Assert.That(actual.done,Is.EqualTo(expected.done).Within(1e-7),label+" real work");Assert.That(actual.eventWork,Is.EqualTo(expected.eventWork).Within(1e-7),label+" separate non-recursive work");}ItemSystemV3.Validate(s);}}}
  [Test]public void LongestFirstAllocationPreservesBudgetAndTreatsTiesFairly(){foreach(var row in Cases().allocations){var actual=ItemSystemV3.DistributeLongestResearchWork(row.remaining,row.budget);Assert.That(actual,Is.EqualTo(row.result).Within(1e-11));Assert.That(actual.Sum(),Is.LessThanOrEqualTo(row.budget+1e-10));for(int i=0;i<actual.Length;i++)Assert.That(actual[i],Is.InRange(0,row.remaining[i]+1e-10));}Assert.Throws<FormatException>(()=>ItemSystemV3.DistributeLongestResearchWork(new[]{double.NaN},1));}
  [Test]public void SplitCreditedTimeKeepsIdenticalCompletionsAndNonRecursiveWork(){var start=Prepared("both");var once=Game.Advance(start,start.SavedAt+40000);var chunks=start;for(int n=0;n<40;n++)chunks=Game.Advance(chunks,start.SavedAt+(n+1)*1000);Assert.That(chunks.Research,Is.EqualTo(once.Research));foreach(var j in PrestigeAutomation.ResearchJobs(once)){var other=PrestigeAutomation.ResearchJobs(chunks).Single(x=>x.id==j.id);Assert.That(other.done,Is.EqualTo(j.done).Within(1e-7));Assert.That(other.eventWork,Is.EqualTo(j.eventWork).Within(1e-7));}Assert.That(start.ResearchJob.done,Is.Zero,"Source copy untouched");}
  [Test]public void IntroNoItemsAndCorruptLedgerCannotGeneratePhotonWorkButPaidIntegrationCan(){var intro=Prepared("both");intro.Quality=0;intro.Story.legacyIntro=false;intro.Story.tutorial="active";intro.Story.target="training";intro=Game.Train(intro,"quality");Assert.That(intro.Training.intro,Is.True);intro.Training.done=intro.Training.required;ItemSystemV3.CompleteTraining(intro,true);Assert.That(PrestigeAutomation.ResearchJobs(intro).Sum(j=>j.eventWork),Is.Zero);var no=Game.Train(Prepared("both"),"quality");no.Challenges.Run=new ChallengeRun{id="no-items",stage=1};no.Training.done=no.Training.required;ItemSystemV3.CompleteTraining(no,true);Assert.That(PrestigeAutomation.ResearchJobs(no).Sum(j=>j.eventWork),Is.Zero);var integration=Prepared("both");integration.Workshop.nodes=new[]{"T04"};integration.Efficiency=1;integration=Game.Train(integration,"integration");Assert.That(integration.Training.id,Is.EqualTo("integration"));integration.Training.done=integration.Training.required;ItemSystemV3.CompleteTraining(integration,true);Assert.That(PrestigeAutomation.ResearchJobs(integration).Sum(j=>j.eventWork),Is.GreaterThan(0));var invalid=Game.Train(Prepared("photon"),"quality");invalid.Training.done=invalid.Training.required;invalid.ResearchJob.eventWork=double.NaN;Assert.Throws<FormatException>(()=>ItemSystemV3.CompleteTraining(invalid,true));Assert.That(invalid.ItemSystemV3.lastCompletedTrainingSequence,Is.Zero);}

 }
}
